#!/bin/sh

aok_preflight_report(){
    r=$(require_active_rootfs) || return; out=$(aok_report_file preflight)
    { echo "rootfs=$r"; echo "host_arch=$ARCH"; echo "rootfs_arch=$(aok_rootfs_arch "$r")"; echo; echo '[required paths]'; for p in /bin/sh /etc/passwd /etc/group /etc/os-release /usr /var /tmp /dev /proc /sys; do [ -e "$r$p" ] && echo "OK $p" || echo "MISSING $p"; done; echo; echo '[shell]'; file "$r/bin/sh" 2>/dev/null || true; echo; echo '[resolv.conf]'; ls -l "$r/etc/resolv.conf" 2>/dev/null; cat "$r/etc/resolv.conf" 2>/dev/null; echo; echo '[init]'; ls -l "$r/sbin/init" "$r/usr/sbin/init" 2>/dev/null; echo; echo '[package manager]'; for x in apt-get apk pacman dnf xbps-install emerge; do [ -x "$r/usr/bin/$x" ] || [ -x "$r/bin/$x" ] || [ -x "$r/usr/sbin/$x" ] || continue; echo "$x"; done; echo; echo '[mount readiness]'; for p in dev proc sys run dev/pts; do [ -d "$r/$p" ] && echo "OK /$p" || echo "MISSING /$p"; done; } >"$out"
    ui_text 'AOK chroot preflight' "$(cat "$out")"
}
aok_broken_symlink_scan(){ r=$(require_active_rootfs)||return; out=$(aok_report_file broken-symlinks); find "$r" -xdev -type l 2>/dev/null | while IFS= read -r l; do t=$(readlink "$l"); case $t in /*) [ -e "$r$t" ] || echo "$l -> $t";; *) [ -e "$(dirname "$l")/$t" ] || echo "$l -> $t";; esac; done >"$out"; ui_text 'Broken symlinks' "$(head -n 500 "$out")"; }
aok_shebang_scan(){ r=$(require_active_rootfs)||return; out=$(aok_report_file shebangs); find "$r/etc" "$r/usr/local" "$r/root" -type f -size -2M 2>/dev/null | while IFS= read -r f; do h=$(sed -n '1p' "$f" 2>/dev/null); case $h in '#!'*) interp=${h#\#!}; interp=${interp%% *}; case $interp in /usr/bin/env) cmd=$(printf '%s' "$h" | awk '{print $2}'); command_path=$(find "$r/bin" "$r/usr/bin" "$r/usr/local/bin" -maxdepth 1 -name "$cmd" 2>/dev/null | head -n1); [ -n "$command_path" ] || echo "MISSING $cmd : ${f#$r}";; /*) [ -e "$r$interp" ] || echo "MISSING $interp : ${f#$r}";; esac;; esac; done >"$out"; ui_text 'Script interpreter audit' "$(head -n 500 "$out")"; }
aok_elf_interpreter_scan(){ r=$(require_active_rootfs)||return; out=$(aok_report_file elf-interpreters); : >"$out"; find "$r/bin" "$r/sbin" "$r/usr/bin" "$r/usr/sbin" -type f 2>/dev/null | while IFS= read -r f; do file "$f" 2>/dev/null | grep -q ELF || continue; if have readelf; then interp=$(readelf -l "$f" 2>/dev/null | sed -n 's/.*Requesting program interpreter: \(.*\)]/\1/p'); [ -n "$interp" ] && { [ -e "$r$interp" ] && state=OK || state=MISSING; printf '%s\t%s\t%s\n' "$state" "$interp" "${f#$r}"; }; fi; done >"$out"; ui_text 'ELF interpreter audit' "$(head -n 500 "$out")"; }
aok_permissions_repair(){ r=$(require_active_rootfs)||return; ui_yesno Permissions "Repair standard permissions in $r?" || return; aok_backup_root_config >/dev/null 2>&1 || true; as_root chmod 1777 "$r/tmp" "$r/var/tmp" 2>/dev/null || true; as_root chmod 755 "$r" "$r/bin" "$r/sbin" "$r/usr" "$r/usr/bin" "$r/usr/sbin" "$r/etc" "$r/var" 2>/dev/null || true; [ -f "$r/etc/shadow" ] && as_root chmod 640 "$r/etc/shadow"; [ -f "$r/etc/gshadow" ] && as_root chmod 640 "$r/etc/gshadow"; [ -d "$r/root" ] && as_root chmod 700 "$r/root"; find "$r/etc/init.d" "$r/usr/local/bin" -type f 2>/dev/null | while IFS= read -r f; do head -c 2 "$f" 2>/dev/null | grep -q '#!' && as_root chmod 755 "$f"; done; ui_msg Permissions 'Standard permissions repaired.'; }
aok_dns_repair(){ r=$(require_active_rootfs)||return; mode=$(ui_menu DNS 'Choose resolver configuration.' host 'Copy host /etc/resolv.conf' cloudflare 'Use Cloudflare 1.1.1.1 and 1.0.0.1' google 'Use Google 8.8.8.8 and 8.8.4.4' quad9 'Use Quad9 9.9.9.9 and 149.112.112.112' custom 'Enter nameservers') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $mode in host) data=$(cat /etc/resolv.conf 2>/dev/null);; cloudflare) data='nameserver 1.1.1.1\nnameserver 1.0.0.1';; google) data='nameserver 8.8.8.8\nnameserver 8.8.4.4';; quad9) data='nameserver 9.9.9.9\nnameserver 149.112.112.112';; custom) n1=$(ui_input DNS 'Primary nameserver:' 1.1.1.1)||return; n2=$(ui_input DNS 'Secondary nameserver:' 1.0.0.1)||return; data="nameserver $n1\nnameserver $n2";; esac; write_file "$r/etc/resolv.conf" 644 "$data"; ui_msg DNS 'Resolver configuration updated.'; }
aok_tmp_runtime_repair(){ r=$(require_active_rootfs)||return; for d in tmp var/tmp run var/run dev/pts proc sys; do as_root mkdir -p "$r/$d"; done; as_root chmod 1777 "$r/tmp" "$r/var/tmp"; [ -L "$r/var/run" ] || { [ -d "$r/var/run" ] && [ -z "$(ls -A "$r/var/run" 2>/dev/null)" ] && as_root rmdir "$r/var/run" 2>/dev/null || true; [ ! -e "$r/var/run" ] && as_root ln -s /run "$r/var/run"; }; ui_msg Runtime 'Runtime directories and temporary permissions repaired.'; }
aok_machine_identity_repair(){ r=$(require_active_rootfs)||return; host=$(ui_input Identity 'Hostname:' "$(basename "$r" | tr -cd '[:alnum:]-' | cut -c1-63)")||return; write_file "$r/etc/hostname" 644 "$host"; [ -s "$r/etc/machine-id" ] || write_file "$r/etc/machine-id" 644 "$(od -An -N16 -tx1 /dev/urandom 2>/dev/null | tr -d ' \n')"; grep -qE '^127\.0\.1\.1' "$r/etc/hosts" 2>/dev/null || append_unique "$r/etc/hosts" "127.0.1.1 $host"; ui_msg Identity 'Hostname, hosts entry and machine-id checked.'; }
aok_package_manager_health(){ r=$(require_active_rootfs)||return; out=$(aok_report_file package-health); { echo "Rootfs: $r"; for cmd in 'dpkg --audit' 'apt-get check' 'apk audit --recursive' 'pacman -Dk' 'rpm -Va --nofiles --nodigest' 'xbps-pkgdb -a'; do bin=${cmd%% *}; if [ -x "$r/usr/bin/$bin" ] || [ -x "$r/bin/$bin" ] || [ -x "$r/usr/sbin/$bin" ]; then echo; echo "[$cmd]"; chroot "$r" sh -c "$cmd" 2>&1 || true; fi; done; } >"$out"; ui_text 'Package-manager health' "$(cat "$out")"; }
aok_config_diff_host(){ r=$(require_active_rootfs)||return; choices=$(ui_checklist 'Host/rootfs comparison' 'Select files to compare.' hosts '/etc/hosts' on resolv '/etc/resolv.conf' on profile '/etc/profile' off sshd '/etc/ssh/sshd_config' off sudo '/etc/sudoers' off)||return; out=$(aok_report_file host-diff); : >"$out"; for x in $choices; do case $x in hosts) f=/etc/hosts;; resolv) f=/etc/resolv.conf;; profile) f=/etc/profile;; sshd) f=/etc/ssh/sshd_config;; sudo) f=/etc/sudoers;; esac; echo "===== $f =====" >>"$out"; diff -u "$f" "$r$f" >>"$out" 2>&1 || true; done; ui_text 'Host/rootfs configuration differences' "$(cat "$out")"; }
aok_archive_wizard(){ r=$(require_active_rootfs)||return; fmt=$(ui_radiolist Archive 'Compression format' zstd 'tar.zst; fast and compact' on gzip 'tar.gz; maximum compatibility' off xz 'tar.xz; smallest but slow' off plain 'uncompressed tar' off)||return; name=$(ui_input Archive 'Archive base name:' "$(basename "$r")-$(date +%Y%m%d-%H%M%S)")||return; case $fmt in zstd) out=$BACKUP_DIR/$name.tar.zst; have zstd || { ui_msg Archive 'zstd is not installed.'; return; }; progress_run 'Creating zstd rootfs archive' sh -c 'tar -C "$1" --numeric-owner -cf - . | zstd -T0 -3 -o "$2"' sh "$r" "$out";; gzip) out=$BACKUP_DIR/$name.tar.gz; progress_run 'Creating gzip rootfs archive' tar -C "$r" --numeric-owner -czf "$out" .;; xz) out=$BACKUP_DIR/$name.tar.xz; progress_run 'Creating xz rootfs archive' tar -C "$r" --numeric-owner -cJf "$out" .;; plain) out=$BACKUP_DIR/$name.tar; progress_run 'Creating rootfs archive' tar -C "$r" --numeric-owner -cf "$out" .;; esac; [ -f "$out" ] && { (sha256sum "$out" 2>/dev/null || shasum -a 256 "$out" 2>/dev/null) >"$out.sha256"; ui_msg Archive "Created $out\nChecksum: $out.sha256"; }; }
aok_rootfs_size_optimizer(){ r=$(require_active_rootfs)||return; choices=$(ui_checklist 'Rootfs size optimizer' 'Select conservative cleanup actions.' cache 'Package caches' on temp 'Temporary files' on logs 'Rotate/truncate logs' on docs 'Documentation' off man 'Manual pages' off info 'Info pages' off pycache 'Python __pycache__ and .pyc files' off npm 'npm cache' off cargo 'Cargo registry cache' off systemd 'systemd journals and coredumps' on)||return; aok_snapshot_create config pre-size-optimize >/dev/null 2>&1 || true; for x in $choices; do case $x in cache) rm -rf "$r/var/cache/apt/archives/"*.deb "$r/var/cache/apk/"* "$r/var/cache/pacman/pkg/"* "$r/var/cache/dnf/"* 2>/dev/null || true;; temp) rm -rf "$r/tmp/"* "$r/var/tmp/"* 2>/dev/null || true;; logs) find "$r/var/log" -type f -exec sh -c ': > "$1"' sh {} \; 2>/dev/null;; docs) rm -rf "$r/usr/share/doc/"* 2>/dev/null;; man) rm -rf "$r/usr/share/man/"* 2>/dev/null;; info) rm -rf "$r/usr/share/info/"* 2>/dev/null;; pycache) find "$r" -xdev \( -type d -name __pycache__ -o -type f -name '*.py[co]' \) -exec rm -rf {} + 2>/dev/null;; npm) rm -rf "$r/root/.npm/_cacache" 2>/dev/null;; cargo) rm -rf "$r/root/.cargo/registry/cache" "$r/root/.cargo/git/checkouts" 2>/dev/null;; systemd) rm -rf "$r/var/log/journal" "$r/var/lib/systemd/coredump" "$r/run/systemd" 2>/dev/null;; esac; done; ui_msg Optimize 'Selected rootfs cleanup actions completed.'; }
aok_service_startup_audit(){ r=$(require_active_rootfs)||return; out=$(aok_report_file startup-services); { echo '[SysV runlevel links]'; find "$r/etc" -path '*/rc?.d/S*' -type l 2>/dev/null | sort; echo; echo '[OpenRC runlevels]'; find "$r/etc/runlevels" -type l 2>/dev/null | sort; echo; echo '[runit services]'; find "$r/etc/service" "$r/var/service" -maxdepth 2 -type l -o -type f 2>/dev/null; echo; echo '[systemd enabled links]'; find "$r/etc/systemd/system" -type l 2>/dev/null | sort; } >"$out"; ui_text 'Rootfs startup audit' "$(cat "$out")"; }
aok_advanced_tools_menu(){ while :; do c=$(ui_menu 'Advanced AOK tools' "Active rootfs: $(active_rootfs)" preflight 'Run chroot and package-manager preflight report' symlinks 'Scan for broken symbolic links' shebangs 'Audit scripts for missing interpreters' elf 'Audit ELF dynamic-linker paths' pkghealth 'Run package-manager health checks' permissions 'Repair standard rootfs permissions' dns 'Repair resolver configuration' runtime 'Repair /tmp, /run, /var/run and mount directories' identity 'Repair hostname, hosts entry and machine-id' services 'Audit enabled startup services' hostdiff 'Compare selected host and rootfs configuration' optimize 'Selectable rootfs size optimizer' archive 'Create checksummed rootfs archive') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in preflight) aok_preflight_report;; symlinks) aok_broken_symlink_scan;; shebangs) aok_shebang_scan;; elf) aok_elf_interpreter_scan;; pkghealth) aok_package_manager_health;; permissions) aok_permissions_repair;; dns) aok_dns_repair;; runtime) aok_tmp_runtime_repair;; identity) aok_machine_identity_repair;; services) aok_service_startup_audit;; hostdiff) aok_config_diff_host;; optimize) aok_rootfs_size_optimizer;; archive) aok_archive_wizard;; esac; done; }
